------------------------------------------------------------
----- ROOT ID FUNCTION FOR: [KnowledgeCategory].[parentID]
------------------------------------------------------------
IF OBJECT_ID('[higherlogic_vanilla].[fnKnowledgeCategoryparentID_GetRootID]', 'IF') IS NOT NULL
    DROP FUNCTION [higherlogic_vanilla].[fnKnowledgeCategoryparentID_GetRootID];
GO

CREATE FUNCTION [higherlogic_vanilla].[fnKnowledgeCategoryparentID_GetRootID]
(
    @RecordID int,
    @ParentID int
)
RETURNS TABLE
AS
RETURN
(
    WITH CTE_RootParent AS (
        SELECT
            [knowledgeCategoryID],
            [parentID],
            [knowledgeCategoryID] AS [RootParentID],
            0 AS [Depth]
        FROM
            [higherlogic_vanilla].[KnowledgeCategory]
        WHERE
            [knowledgeCategoryID] = COALESCE(@ParentID, @RecordID)

        UNION ALL

        SELECT
            c.[knowledgeCategoryID],
            c.[parentID],
            c.[knowledgeCategoryID] AS [RootParentID],
            p.[Depth] + 1 AS [Depth]
        FROM
            [higherlogic_vanilla].[KnowledgeCategory] c
        INNER JOIN
            CTE_RootParent p ON c.[knowledgeCategoryID] = p.[parentID]
        WHERE
            p.[Depth] < 100
    )
    SELECT TOP 1
        [RootParentID] AS RootID
    FROM
        CTE_RootParent
    WHERE
        [parentID] IS NULL
    ORDER BY
        [RootParentID]
);
GO

