------------------------------------------------------------
----- ROOT ID FUNCTION FOR: [Tag].[parentTagID]
------------------------------------------------------------
IF OBJECT_ID('[higherlogic_vanilla].[fnTagparentTagID_GetRootID]', 'IF') IS NOT NULL
    DROP FUNCTION [higherlogic_vanilla].[fnTagparentTagID_GetRootID];
GO

CREATE FUNCTION [higherlogic_vanilla].[fnTagparentTagID_GetRootID]
(
    @RecordID int,
    @ParentID int
)
RETURNS TABLE
AS
RETURN
(
    WITH CTE_RootParent AS (
        SELECT
            [tagID],
            [parentTagID],
            [tagID] AS [RootParentID],
            0 AS [Depth]
        FROM
            [higherlogic_vanilla].[Tag]
        WHERE
            [tagID] = COALESCE(@ParentID, @RecordID)

        UNION ALL

        SELECT
            c.[tagID],
            c.[parentTagID],
            c.[tagID] AS [RootParentID],
            p.[Depth] + 1 AS [Depth]
        FROM
            [higherlogic_vanilla].[Tag] c
        INNER JOIN
            CTE_RootParent p ON c.[tagID] = p.[parentTagID]
        WHERE
            p.[Depth] < 100
    )
    SELECT TOP 1
        [RootParentID] AS RootID
    FROM
        CTE_RootParent
    WHERE
        [parentTagID] IS NULL
    ORDER BY
        [RootParentID]
);
GO

